<script setup lang="ts">import{computed,ref}from'vue';import{CheckCircle2,Volume2,RefreshCw,XCircle}from'lucide-vue-next';import GuitarFretboard from'./GuitarFretboard.vue';import{fretMidi}from'../engines/guitar/fretboard';import{midiName,midiHz}from'../engines/music/pitch';import{useProgress}from'../composables/useProgress';const{record,complete}=useProgress();const pool=[40,42,45,47,50,52,55,57,59,60,62,64,65,67,69];const round=ref(0),target=ref(52),selected=ref<{string:number;fret:number}|null>(null),answered=ref(false),correct=ref(false);const name=computed(()=>midiName(target.value));function choose(p:{string:number;fret:number;midi:number}){if(!answered.value)selected.value=p}function check(){if(!selected.value)return;correct.value=fretMidi(selected.value.string,selected.value.fret)===target.value;answered.value=true;record(correct.value);if(correct.value)complete(1)}function next(){round.value++;target.value=pool[(round.value*7+3)%pool.length];selected.value=null;answered.value=false}function play(){const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.frequency.value=midiHz(target.value);o.type='sine';g.gain.setValueAtTime(.14,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+1);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+1);o.onended=()=>c.close()}</script><template><section class="panel p-5 sm:p-7"><div class="flex justify-between gap-3"><div><p class="eyebrow">Reto de notas · Nivel 1</p><h2 class="mt-1 text-2xl font-black">Encuentra la nota</h2><p class="mt-1 text-sm text-[#788780]">Escucha y localiza la nota en el diapasón.</p></div><span class="rounded-full bg-[#eef4ef] px-3 py-1.5 text-xs font-bold text-[#426c5b]">Ronda {{round+1}}</span></div><div class="my-6 flex items-center justify-center gap-4 rounded-2xl bg-[#f5f8f4] p-5"><div class="text-center"><p class="text-xs font-bold uppercase text-[#718078]">Busca esta nota</p><p class="mt-1 text-4xl font-black text-[#176b5b]">{{name.name}}</p><p class="text-sm text-[#75827b]">Octava {{name.octave}}</p></div><button class="secondary flex items-center gap-2" @click="play"><Volume2 :size="19"/> Escuchar</button></div><GuitarFretboard :selected="selected" :disabled="answered" @select="choose"/><div class="mt-5 flex flex-wrap items-center justify-between gap-3"><p class="text-sm text-[#788780]">Toca una cuerda y un traste.</p><button class="primary disabled:opacity-40" :disabled="!selected||answered" @click="check">Comprobar</button></div><div v-if="answered" class="mt-4 flex items-center gap-3 rounded-xl p-4" :class="correct?'bg-[#e9f5ed] text-[#226447]':'bg-[#fff1e9] text-[#a14f2d]'"><CheckCircle2 v-if="correct"/><XCircle v-else/><p class="flex-1 text-sm font-semibold">{{correct?'¡Muy bien! Encontraste la nota.':'Casi. La nota correcta es '+name.name+'.'}}</p><button class="rounded-lg p-2" aria-label="Siguiente ejercicio" @click="next"><RefreshCw/></button></div></section></template>